do $$ begin if to_regclass('public.fin_service_accounts') is not null or to_regclass('public.fin_api_credentials') is not null or to_regclass('public.fin_webhook_endpoints') is not null or to_regclass('public.fin_webhook_deliveries') is not null or to_regprocedure('public.fin_api_context(text,text)') is not null or exists (select 1 from pg_trigger where tgname = 'fin_webhook_capture') or (select value from public.fin_settings where key='schema_version') <> 'financial-policy-engine-1' then raise exception 'Public API rollback incomplete'; end if; end $$;
